import { LinkedListNode } from './linked-list-node';

export class LinkedListNodePool<T> {
    private poolReversedListTail?: LinkedListNode<T>;

    public addNodeToPool(node: LinkedListNode<T>): void {
        node.previous = this.poolReversedListTail;
        this.poolReversedListTail = node;
    }

    public getNodeFromPool(): LinkedListNode<T> {
        if (this.poolReversedListTail) {
            const node: LinkedListNode<T> = this.poolReversedListTail;
            this.poolReversedListTail = node.previous;
            node.previous = void 0;
            return node;
        }
        return new LinkedListNode<T>();
    }
}
